import { MeshStandardNodeMaterial, MeshBasicNodeMaterial } from 'three/webgpu';
import { uv, vec2, distance, smoothstep, oneMinus } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, PlaneGeometry, BoxGeometry, Mesh, Color, DirectionalLight, PointLight } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const group = new Group();
  group.name = 'journal-thumbnail-card';

  // --- geometry sizing from atlas source rect (512x320 => 1.6 aspect) ---
  const imgW = 1.7;
  const imgH = imgW / (512 / 320);
  const capH = 0.32;
  const totalH = imgH + capH;

  const imgY = totalH / 2 - imgH / 2;
  const capY = totalH / 2 - imgH - capH / 2;
  const edgeY = capY + capH / 2 - 0.008;

  const disposables = [];

  // --- backing frame (extruded body for a "real" 3D card, not a flat rect) ---
  const frameGeo = new BoxGeometry(imgW + 0.12, totalH + 0.12, 0.06);
  const frameMat = new MeshStandardNodeMaterial({
    color: new Color(colors.surface),
    roughness: 0.6,
    metalness: 0.35,
    clearcoat: 0.15,
  });
  const frame = new Mesh(frameGeo, frameMat);
  frame.position.set(0, 0, -0.04);
  group.add(frame);
  disposables.push(frameGeo, frameMat);

  // --- focus/accent outline (hidden by default, revealed on hover/focus) ---
  const focusGeo = new BoxGeometry(imgW + 0.18, totalH + 0.18, 0.04);
  const focusMat = new MeshBasicNodeMaterial({
    color: new Color(colors.accent),
    transparent: true,
    opacity: 0,
  });
  const focusEdge = new Mesh(focusGeo, focusMat);
  focusEdge.position.set(0, 0, -0.06);
  group.add(focusEdge);
  disposables.push(focusGeo, focusMat);

  // --- image plane ---
  const imgGeo = new PlaneGeometry(imgW, imgH);
  const imgMat = new MeshStandardNodeMaterial({
    color: new Color(colors.paper),
    roughness: 0.55,
    metalness: 0.1,
  });
  const imagePlane = new Mesh(imgGeo, imgMat);
  imagePlane.position.set(0, imgY, 0.035);
  group.add(imagePlane);
  disposables.push(imgGeo, imgMat);

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      imgMat.map = tex;
      imgMat.needsUpdate = true;
    }).catch(() => {});
  }

  // --- caption strip ---
  const capGeo = new BoxGeometry(imgW, capH, 0.05);
  const capMat = new MeshStandardNodeMaterial({
    color: new Color(colors.ink),
    roughness: 0.55,
    metalness: 0.3,
  });
  const captionStrip = new Mesh(capGeo, capMat);
  captionStrip.position.set(0, capY, 0.03);
  group.add(captionStrip);
  disposables.push(capGeo, capMat);

  // --- accent divider between image and caption ---
  const edgeGeo = new BoxGeometry(imgW, 0.018, 0.06);
  const edgeMat = new MeshStandardNodeMaterial({
    color: new Color(colors.accent),
    roughness: 0.5,
    metalness: 0.2,
    emissive: new Color(colors.accent),
    emissiveIntensity: 0.6,
  });
  const accentDivider = new Mesh(edgeGeo, edgeMat);
  accentDivider.position.set(0, edgeY, 0.045);
  group.add(accentDivider);
  disposables.push(edgeGeo, edgeMat);

  // --- soft depth shadow behind card (radial falloff via TSL) ---
  const shadowGeo = new PlaneGeometry(imgW + 0.9, totalH + 0.9);
  const dist = distance(uv(), vec2(0.5, 0.5));
  const alpha = oneMinus(smoothstep(0.0, 0.5, dist)).mul(0.45);
  const shadowMat = new MeshBasicNodeMaterial({
    color: new Color('#000000'),
    transparent: true,
    depthWrite: false,
  });
  shadowMat.opacityNode = alpha;
  const shadowPlane = new Mesh(shadowGeo, shadowMat);
  shadowPlane.position.set(0, 0, -0.12);
  group.add(shadowPlane);
  disposables.push(shadowGeo, shadowMat);

  // --- local rim/accent light (node-local, within intensity budget) ---
  const rimLight = new PointLight(new Color(colors.accent), 0.8, 4);
  rimLight.position.set(0.8, 0.6, 0.9);
  group.add(rimLight);

  // --- motion: hover rise-in (subtle, 0.15 units) ---
  const baseY = group.position.y || 0;
  const hoverTl = gsap.timeline({ paused: true });
  hoverTl.to(group.position, { y: '+=0.15', duration: 0.5, ease: 'power3.out' }, 0);
  hoverTl.to(group.scale, { x: 1.02, y: 1.02, z: 1.02, duration: 0.5, ease: 'power3.out' }, 0);
  hoverTl.to(focusMat, { opacity: 0.7, duration: 0.3, ease: 'power2.out' }, 0);
  hoverTl.to(rimLight, { intensity: 1.3, duration: 0.3, ease: 'power2.out' }, 0);

  // --- motion: press-down on click ---
  const pressTl = gsap.timeline({ paused: true });
  pressTl.to(group.scale, {
    x: 0.97, y: 0.97, z: 0.97,
    duration: 0.12, ease: 'back.out(2)',
    yoyo: true, repeat: 1,
  });

  const nodeId = config.id ?? config.nodeId ?? 'hub-journal-thumbnail';

  const onPointerEnter = () => hoverTl.play();
  const onPointerLeave = () => hoverTl.reverse();
  const onPointerDown = () => pressTl.restart();
  const onClick = () => {
    ctx.emit('hub-journal.select', { nodeId, itemId: config.itemId ?? nodeId });
  };

  group.userData.handlers = {
    onPointerEnter,
    onPointerLeave,
    onPointerDown,
    onClick,
    hover: onPointerEnter,
    pointerover: onPointerEnter,
    pointerenter: onPointerEnter,
    pointerout: onPointerLeave,
    pointerleave: onPointerLeave,
    pointerdown: onPointerDown,
    click: onClick,
  };

  group.userData.cleanup = () => {
    hoverTl.kill();
    pressTl.kill();
    group.remove(rimLight);
    for (const d of disposables) {
      if (d && typeof d.dispose === 'function') d.dispose();
    }
    if (imgMat.map && typeof imgMat.map.dispose === 'function') {
      imgMat.map.dispose();
    }
  };

  return group;
}
